#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.18991099, -0.215785775, 0.39564654], 'basis': [[0.0, 0.9999986586409371, 0.0016378999746010253], [-0.9467673383788733, -0.0005272705226113426, 0.3219182022886872], [0.3219186340971646, -0.0015507101994838368, 0.9467660684239234]], 'axis': [0.0016378999746010253, 0.3219182022886872, 0.9467660684239234], 'zmin': -0.10442128963643586, 'zmax': 0.10436414091468527, 'profiles': [{'outer': [[-0.10438753740353202, -0.005987172865236114], [-0.1042743065242566, 0.005948794294330179], [-0.10223635809040586, 0.014562718374267996], [-0.1020068166570975, 0.01610846154007838], [-0.10214198463896774, 0.021751289599166227], [-0.10147125428808093, 0.02542746369702724], [-0.10019874614650053, 0.027028038128577007], [-0.09538764261575677, 0.02709336821901868], [-0.078978674728809, 0.03050986184178168], [-0.029088851685786673, 0.030619130339975105], [-0.029088851685786673, 0.031063963063931315], [-0.027326093981479185, 0.031072460550588828], [-0.027326093981479185, 0.032572162751376046], [-0.021576158179016477, 0.03257536498653209], [-0.021576158179016477, 0.031071465709581032], [-0.02143966964406036, 0.031071264990734627], [-0.01980284146343066, 0.03111162129982526], [-0.01980284146343066, 0.032611706970651695], [-0.0191893045538067, 0.03261642014191765], [-0.014052896193294546, 0.032614909211080435], [-0.014052896193294546, 0.031110939915445567], [-0.012416068012664847, 0.031108602809719357], [-0.012416068012664847, 0.03087341707225781], [-0.012141671817771996, 0.030873875850533264], [-0.012141671817771996, 0.0310337521659328], [-0.010772883791041814, 0.031041646653166888], [-0.010504843637142297, 0.031692941825148556], [-0.010504843637142297, 0.03254188172112532], [-0.004754907834679589, 0.032545083956281355], [-0.004754907834679589, 0.03188814300237347], [0.004838819444108792, 0.03188829754662611], [0.004838819444108792, 0.03262021546917371], [0.010588764714244907, 0.032623417709602455], [0.010588764714244907, 0.031616455701214664], [0.010814007077695757, 0.03111914569484939], [0.012225592894874605, 0.03111711130824138], [0.012225592894874605, 0.030873895642910876], [0.012485734912420901, 0.030873474641182192], [0.012485734912420901, 0.031042329226314423], [0.014122582028397382, 0.031050756487465612], [0.014122582028397382, 0.03255045879205235], [0.019872527298533497, 0.0325536610324811], [0.019872527298533497, 0.031049761699316364], [0.020023260922934036, 0.03104954003517488], [0.02178599969189474, 0.031089918675661292], [0.02178599969189474, 0.03259000446758717], [0.02741003437369982, 0.032593136586309114], [0.02741003437369982, 0.031089255899530727], [0.029130802946550207, 0.03108687693275257], [0.029130802946550207, 0.030619668631938594], [0.07854274619778999, 0.030515452173864106], [0.07906260887254257, 0.030488363064674142], [0.09553018453038314, 0.027092495460759834], [0.10108023822061954, 0.027043656662456395], [0.10222773420946103, 0.025444506592920163], [0.1043875213076003, 0.005942833002247481], [0.1043875213076003, -0.0038984437970489886], [0.1042743065242566, -0.0059931342348543215], [0.10232027954727976, -0.014606981577573242], [0.10202112715303374, -0.016611285786688346], [0.10208573110294815, -0.0217955841603751], [0.1014292746242972, -0.02542747707621563], [0.1002264235350282, -0.02707228594725405], [0.09547902656514785, -0.027137598373695268], [0.07906260887254257, -0.030642834936329383], [0.029130802946550207, -0.030752127799571486], [0.029130802946550207, -0.031063919700601295], [0.02741003437369982, -0.0310720102289724], [0.02741003437369982, -0.03257211600357151], [0.02178599969189474, -0.032575248122293454], [0.02178599969189474, -0.031071592370607738], [0.021509355479163196, -0.031071184243766828], [0.019872527298533497, -0.031111562490648188], [0.019872527298533497, -0.032611591557399525], [0.01632101947537448, -0.03261794082987241], [0.014122582028397382, -0.03261479379782827], [0.014122582028397382, -0.03111090434889894], [0.012485734912420901, -0.03110846740703944], [0.012485734912420901, -0.030873373105307637], [0.012225592894874605, -0.030873800637504546], [0.012225592894874605, -0.031033685325112484], [0.010822882855658933, -0.031041598807880665], [0.010588764714244907, -0.03151392413054612], [0.010588764714244907, -0.03254183488027817], [0.004838819444108792, -0.032545037120706916], [0.004838819444108792, -0.03188850178012365], [-0.010407848795455841, -0.03187554909517151], [-0.010861767503422054, -0.03087602873648991], [-0.017355632123952913, -0.03085744237496084], [-0.01744720455955621, -0.03075832848799027], [-0.07854275566546343, -0.03064847200070924], [-0.078978674728809, -0.030621336159221847], [-0.0955916295806094, -0.027136539516864736], [-0.1010382553376495, -0.02708797323931267], [-0.10214379381724038, -0.025444449845129048]], 'holes': []}], 'simplify_tolerance': 4.175501174222647e-05, 'sketch_entity_count': 98}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
